return items
  .filter(item => {
    const cnpj = String(item.json.CNPJ ?? '').trim();
    const telefone = String(item.json.TELEFONE ?? '').trim();
    return cnpj.length > 0 && telefone.length > 0;
  })
  .map(item => ({
    json: {
      ...item.json,
      CNPJ: String(item.json.CNPJ ?? '').trim(),
      TELEFONE: String(item.json.TELEFONE ?? '').trim(),
      TELEFONE_ORIGINAL: String(item.json.TELEFONE ?? '').trim()
    }
  }));

const inputItems = $input.all();

return inputItems.map((item, index) => {
  const base = item.json ?? {};
  const original = String(base.TELEFONE ?? '').trim();
  const digits = original.replace(/\D/g, '');

  let e164Digits = digits;
  if (e164Digits && !e164Digits.startsWith('55') && (e164Digits.length === 10 || e164Digits.length === 11)) {
    e164Digits = '55' + e164Digits;
  }

  let localDigits = e164Digits;
  if (localDigits.startsWith('55') && (localDigits.length === 12 || localDigits.length === 13)) {
    localDigits = localDigits.slice(2);
  }

  let localFormatted = '';
  if (localDigits.length === 11) {
    localFormatted = `(${localDigits.slice(0, 2)}) ${localDigits.slice(2, 7)}-${localDigits.slice(7)}`;
  } else if (localDigits.length === 10) {
    localFormatted = `(${localDigits.slice(0, 2)}) ${localDigits.slice(2, 6)}-${localDigits.slice(6)}`;
  }

  const e164Formatted = localFormatted
    ? `+55 ${localFormatted}`
    : (e164Digits ? `+${e164Digits}` : '');

  return {
    json: {
      CNPJ: String(base.CNPJ ?? '').trim(),
      TELEFONE: e164Digits,
      TELEFONE_ORIGINAL: original,
      TELEFONE_DIGITOS_ORIGINAL: digits,
      TELEFONE_LOCAL: localDigits,
      TELEFONE_LOCAL_FORMATADO: localFormatted,
      TELEFONE_E164_FORMATADO: e164Formatted,
      CONSULTOR_ATUAL: String(base.CONSULTOR ?? '').trim()
    },
    pairedItem: { item: index }
  };
});

const p = $('Preparar Busca Chatwoot').item.json;
const atual = String(p.CONSULTOR_ATUAL ?? '').trim();

const NOMES_PROIBIDOS = ["CONSULTOR_INATIVO_A", "CONSULTOR_INATIVO_B", "CONSULTOR_INATIVO_C"];
function normalizarNome(valor) {
  return String(valor ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .trim().replace(/\s+/g, ' ').toLowerCase();
}
const atualEhProibido = NOMES_PROIBIDOS.map(normalizarNome).includes(normalizarNome(atual));
const precisaAtualizar = atualEhProibido && normalizarNome(atual) !== normalizarNome('RESPONSAVEL_PADRAO');

return {
  json: {
    ...p,
    consultor_final: precisaAtualizar ? 'RESPONSAVEL_PADRAO' : atual,
    acao: precisaAtualizar ? 'ATUALIZAR' : 'IGNORAR',
    motivo: atualEhProibido
      ? 'CONTATO_NAO_ENCONTRADO_CONSULTOR_PROIBIDO_TROCAR_PARA_RESPONSAVEL_PADRAO'
      : 'CONTATO_NAO_ENCONTRADO_MANTER_CONSULTOR_ATUAL'
  }
};

const itens = $input.all();
const primeiro = itens[0]?.json ?? {};
const p = {
  CNPJ: primeiro.CNPJ ?? '',
  TELEFONE: primeiro.TELEFONE ?? '',
  TELEFONE_ORIGINAL: primeiro.TELEFONE_ORIGINAL ?? '',
  TELEFONE_DIGITOS_ORIGINAL: primeiro.TELEFONE_DIGITOS_ORIGINAL ?? '',
  TELEFONE_LOCAL: primeiro.TELEFONE_LOCAL ?? '',
  TELEFONE_LOCAL_FORMATADO: primeiro.TELEFONE_LOCAL_FORMATADO ?? '',
  TELEFONE_E164_FORMATADO: primeiro.TELEFONE_E164_FORMATADO ?? '',
  CONSULTOR_ATUAL: primeiro.CONSULTOR_ATUAL ?? ''
};

const NOMES_ACEITOS = ["CONSULTOR_A", "CONSULTOR_B", "CONSULTOR_C", "CONSULTOR_D", "CONSULTOR_E"];

const NOMES_PROIBIDOS = ["CONSULTOR_INATIVO_A", "CONSULTOR_INATIVO_B", "CONSULTOR_INATIVO_C"];

function norm(v) {
  return String(v ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim()
    .replace(/\s+/g, ' ')
    .toLowerCase();
}

function ts(v) {
  if (v === null || v === undefined || v === '') return 0;
  if (typeof v === 'number') return v > 1e12 ? Math.floor(v / 1000) : Math.floor(v);
  const n = Number(v);
  if (Number.isFinite(n)) return n > 1e12 ? Math.floor(n / 1000) : Math.floor(n);
  const ms = Date.parse(v);
  return Number.isNaN(ms) ? 0 : Math.floor(ms / 1000);
}

const aceitos = new Map(NOMES_ACEITOS.map(n => [norm(n), n]));
const proibidos = new Set(NOMES_PROIBIDOS.map(norm));

const atual = String(p.CONSULTOR_ATUAL ?? '').trim();
const atualNorm = norm(atual);
const atualPermitido = aceitos.has(atualNorm);
const atualProibido = proibidos.has(atualNorm);
const atualSdr = atualNorm === norm('RESPONSAVEL_PADRAO');

if (atualPermitido) {
  return [{
    json: {
      ...p,
      consultor_final: atual,
      consultor_historico_encontrado: null,
      origem_consultor_historico: null,
      historico_dentro_30_dias: null,
      acao: 'IGNORAR',
      motivo: 'CONSULTOR_ATUAL_JA_PERMITIDO',
      conversas_analisadas: itens.length,
      mensagens_analisadas: 0,
      candidatos_permitidos_encontrados: 0
    }
  }];
}

const candidatos = [];
let mensagensAnalisadas = 0;
let conversasAnalisadas = 0;

for (const item of itens) {
  const j = item.json ?? {};

  if (j.sem_conversas === true) continue;
  conversasAnalisadas++;

  const resposta = j.resposta_mensagens ?? {};
  const mensagens = Array.isArray(resposta.payload)
    ? resposta.payload
    : Array.isArray(resposta.messages)
      ? resposta.messages
      : [];

  mensagensAnalisadas += mensagens.length;

  // O endpoint de mensagens também devolve meta.assignee.
  const assigneeNome =
    resposta?.meta?.assignee?.name ??
    resposta?.meta?.assignee?.available_name ??
    j?.conversation_assignee_name ??
    '';

  const assigneeNorm = norm(assigneeNome);
  if (assigneeNorm && aceitos.has(assigneeNorm) && !proibidos.has(assigneeNorm)) {
    candidatos.push({
      nome: aceitos.get(assigneeNorm),
      timestamp: ts(j.conversation_last_activity_at),
      fonte: 'ASSIGNEE_CONVERSA',
      conversation_id: j.conversation_id
    });
  }

  for (const m of mensagens) {
    // Mensagem privada / nota interna NÃO define quem foi o consultor da conversa.
    const ehPrivada =
      m?.private === true ||
      String(m?.private ?? '').toLowerCase() === 'true' ||
      m?.is_private === true ||
      String(m?.is_private ?? '').toLowerCase() === 'true';

    if (ehPrivada) continue;

    const nome =
      m?.sender?.name ??
      m?.sender?.available_name ??
      m?.sender?.display_name ??
      '';

    const nomeNorm = norm(nome);
    if (!nomeNorm || !aceitos.has(nomeNorm) || proibidos.has(nomeNorm)) continue;

    candidatos.push({
      nome: aceitos.get(nomeNorm),
      timestamp: ts(m?.created_at ?? m?.updated_at ?? j.conversation_last_activity_at),
      fonte: 'MENSAGEM_PUBLICA_AGENTE',
      conversation_id: j.conversation_id ?? m?.conversation_id ?? null,
      message_id: m?.id ?? null
    });
  }
}

// Ordena pelo evento mais recente.
candidatos.sort((a, b) => b.timestamp - a.timestamp);

const agora = Math.floor(Date.now() / 1000);
const limite30 = agora - 30 * 24 * 60 * 60;

const recentes = candidatos.filter(c => c.timestamp >= limite30);
const antigos = candidatos.filter(c => c.timestamp < limite30);

// Prioridade: mais recente permitido dentro de 30 dias.
// Se não houver, mais recente permitido antigo.
const escolhido = recentes[0] ?? antigos[0] ?? null;

if (escolhido) {
  const precisaAtualizar = atualNorm !== norm(escolhido.nome);

  let motivo;
  if (atualSdr) {
    motivo = escolhido.timestamp >= limite30
      ? 'RESPONSAVEL_PADRAO_SUBSTITUIR_POR_PERMITIDO_RECENTE'
      : 'RESPONSAVEL_PADRAO_SUBSTITUIR_POR_PERMITIDO_ANTIGO';
  } else if (atualProibido) {
    motivo = escolhido.timestamp >= limite30
      ? 'PROIBIDO_SUBSTITUIR_POR_PERMITIDO_RECENTE'
      : 'PROIBIDO_SUBSTITUIR_POR_PERMITIDO_ANTIGO';
  } else {
    motivo = escolhido.timestamp >= limite30
      ? 'VALOR_NAO_PERMITIDO_SUBSTITUIR_POR_PERMITIDO_RECENTE'
      : 'VALOR_NAO_PERMITIDO_SUBSTITUIR_POR_PERMITIDO_ANTIGO';
  }

  return [{
    json: {
      ...p,
      consultor_final: precisaAtualizar ? escolhido.nome : atual,
      consultor_historico_encontrado: escolhido.nome,
      origem_consultor_historico: escolhido.fonte,
      historico_dentro_30_dias: escolhido.timestamp >= limite30,
      acao: precisaAtualizar ? 'ATUALIZAR' : 'IGNORAR',
      motivo: precisaAtualizar ? motivo : 'CONSULTOR_ATUAL_JA_IGUAL_AO_ENCONTRADO',
      conversation_id: escolhido.conversation_id,
      message_id: escolhido.message_id ?? null,
      last_activity_at: escolhido.timestamp,
      conversas_analisadas: conversasAnalisadas,
      mensagens_analisadas: mensagensAnalisadas,
      candidatos_permitidos_encontrados: candidatos.length,
      candidatos_permitidos_recentes: recentes.length
    }
  }];
}

// Não achou nenhum permitido no histórico efetivamente buscado.
if (atualProibido) {
  return [{
    json: {
      ...p,
      consultor_final: 'RESPONSAVEL_PADRAO',
      consultor_historico_encontrado: null,
      origem_consultor_historico: null,
      historico_dentro_30_dias: false,
      acao: atualNorm === norm('RESPONSAVEL_PADRAO') ? 'IGNORAR' : 'ATUALIZAR',
      motivo: 'NENHUM_PERMITIDO_NAS_MENSAGENS_E_ATUAL_PROIBIDO',
      conversas_analisadas: conversasAnalisadas,
      mensagens_analisadas: mensagensAnalisadas,
      candidatos_permitidos_encontrados: 0,
      candidatos_permitidos_recentes: 0
    }
  }];
}

return [{
  json: {
    ...p,
    consultor_final: atual,
    consultor_historico_encontrado: null,
    origem_consultor_historico: null,
    historico_dentro_30_dias: false,
    acao: 'IGNORAR',
    motivo: conversasAnalisadas > 0
      ? 'MENSAGENS_BUSCADAS_MAS_NENHUM_CONSULTOR_PERMITIDO_ENCONTRADO'
      : 'SEM_CONVERSAS',
    conversas_analisadas: conversasAnalisadas,
    mensagens_analisadas: mensagensAnalisadas,
    candidatos_permitidos_encontrados: 0,
    candidatos_permitidos_recentes: 0
  }
}];

const origem = $json ?? {};
const p = $('Preparar Busca Chatwoot').item.json;

const conversas = Array.isArray(origem.payload)
  ? origem.payload
  : Array.isArray(origem.conversations)
    ? origem.conversations
    : [];

if (conversas.length === 0) {
  return [{
    json: {
      ...p,
      sem_conversas: true,
      conversation_id: null,
      conversation_last_activity_at: null,
      conversation_assignee_name: ''
    }
  }];
}

return conversas.map((c) => ({
  json: {
    ...p,
    sem_conversas: false,
    conversation_id: c?.id ?? null,
    conversation_last_activity_at:
      c?.last_activity_at ?? c?.timestamp ?? c?.updated_at ?? c?.created_at ?? null,
    conversation_assignee_name:
      c?.meta?.assignee?.name ??
      c?.meta?.assignee?.available_name ??
      c?.assignee?.name ??
      ''
  },
  pairedItem: { item: 0 }
}));

const contexto = $('Preparar Conversas para Mensagens').item.json;
return {
  json: {
    ...contexto,
    resposta_mensagens: $json
  }
};
